  private readonly entries = new Map<string, Entry>();

  constructor(files: readonly TransferFile[], private readonly chunkSize: number, private readonly maxConcurrent: number) {
    if (!Number.isInteger(chunkSize) || chunkSize <= 0 || !Number.isInteger(maxConcurrent) || maxConcurrent <= 0) {
      throw new RangeError("chunkSize and maxConcurrent must be positive integers");
    }
    for (const file of files) {
      if (file.id.length === 0 || this.entries.has(file.id)) throw new RangeError("file IDs must be non-empty and unique");
      if (!Number.isInteger(file.size) || file.size < 0) throw new RangeError("file size must be a non-negative integer");
      this.entries.set(file.id, {
        id: file.id,
        size: file.size,
        accepted: 0,
        status: file.size === 0 ? "completed" : "queued",
        activeLength: 0,
        pauseAfter: false,
      });
    }
  }

