import { ChunkTransferQueue } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throws(action: () => unknown, ctor: Function, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof (ctor as typeof Error), message);
}
function assertNoSharedObjects(a: unknown, b: unknown, message: string): void {
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) return;
  assert(a !== b, message);
  const aa = a as Record<string, unknown>;
  const bb = b as Record<string, unknown>;
  for (const key of Object.keys(aa)) {
    if (key in bb) assertNoSharedObjects(aa[key], bb[key], message);
  }
}

for (const make of [
  () => new ChunkTransferQueue([], 0, 1),
  () => new ChunkTransferQueue([], 1.5, 1),
  () => new ChunkTransferQueue([], 1, 0),
  () => new ChunkTransferQueue([], 1, Number.POSITIVE_INFINITY),
  () => new ChunkTransferQueue([{ id: '', size: 1 }], 1, 1),
  () => new ChunkTransferQueue([{ id: 'a', size: -1 }], 1, 1),
  () => new ChunkTransferQueue([{ id: 'a', size: 1.2 }], 1, 1),
  () => new ChunkTransferQueue([{ id: 'a', size: 1 }, { id: 'a', size: 2 }], 1, 1)
]) throws(make, RangeError, 'invalid constructor input must throw RangeError');

const files = [{ id: 'a', size: 5 }, { id: 'zero', size: 0 }, { id: 'c', size: 4 }];
const queue = new ChunkTransferQueue(files, 3, 2);
files[0].id = 'changed';
files[0].size = 99;
files.push({ id: 'late', size: 1 });

const batch1 = queue.nextBatch();
equal(batch1, [
  { fileId: 'a', offset: 0, length: 3 },
  { fileId: 'c', offset: 0, length: 3 }
], 'initial scheduling order and zero-byte completion');
assert(batch1[0] !== batch1[1], 'jobs must be distinct objects');
assert(queue.nextBatch().length === 0, 'in-flight jobs consume concurrency');

batch1[0].length = 99;
throws(() => queue.completeChunk('a', 2), Error, 'completion length must match');
queue.completeChunk('a', 3);
equal(queue.nextBatch(), [{ fileId: 'a', offset: 3, length: 2 }], 'exact final chunk');
queue.completeChunk('c', 3);
equal(queue.nextBatch(), [{ fileId: 'c', offset: 3, length: 1 }], 'short final chunk');
queue.completeChunk('a', 2);
queue.completeChunk('c', 1);
assert(queue.nextBatch().length === 0, 'completed files must not reschedule');

const retrying = new ChunkTransferQueue([{ id: 'x', size: 3 }], 2, 1);
equal(retrying.nextBatch(), [{ fileId: 'x', offset: 0, length: 2 }], 'first retry fixture job');
retrying.failChunk('x');
assert(retrying.nextBatch().length === 0, 'failed file requires explicit retry');
retrying.retry('x');
equal(retrying.nextBatch(), [{ fileId: 'x', offset: 0, length: 2 }], 'retry must not advance progress');
retrying.completeChunk('x', 2);

const pausing = new ChunkTransferQueue([{ id: 'p', size: 4 }], 2, 1);
pausing.nextBatch();
pausing.pause('p');
pausing.completeChunk('p', 2);
assert(pausing.nextBatch().length === 0, 'in-flight pause takes effect after completion');
pausing.resume('p');
equal(pausing.nextBatch(), [{ fileId: 'p', offset: 2, length: 2 }], 'resume continues at accepted byte count');

const cancelled = new ChunkTransferQueue([{ id: 'z', size: 1 }], 1, 1);
cancelled.cancel('z');
assert(cancelled.nextBatch().length === 0, 'cancelled file is terminal');
throws(() => cancelled.resume('z'), Error, 'cancelled file cannot resume');
cancelled.remove('z');
throws(() => cancelled.pause('z'), Error, 'removed ID is unknown');
throws(() => cancelled.remove('missing'), Error, 'unknown removal must throw');

const snapQueue = new ChunkTransferQueue([{ id: 's', size: 2 }], 1, 1);
const snapshot1 = snapQueue.snapshot();
const snapshot2 = snapQueue.snapshot();
equal(snapshot1, snapshot2, 'stable snapshots without state changes');
assertNoSharedObjects(snapshot1, snapshot2, 'snapshots must not share objects');
throws(() => snapQueue.completeChunk('missing', 1), Error, 'unknown completion must throw');

